// v23.xx (gfx11), HIS ORDER (2026-10-12) on the graphics program, item 2, shadows that follow light: BODY SHADOWS FROM LAMPS.
// Under LIGHTING HIGH a body standing in a lamp's pool throws a shadow along the ground away from that lamp, as well as the soft
// shadow under its feet: up to two, from the two lamps that light it most. Close to a lamp the shadow is short and dark, toward
// the edge of the pool it stretches and fades, and a lamp behind a wall casts none (the wall already shades him). Bodies are him,
// the machines and pillagers in sight (VIS, never G.ents: an unseen body never casts a shadow you could read through the fog) and
// the party members drawn up top. Each shadow is the baked ground shadow stamp (v18.36, SHADSPR), turned to point away from the
// lamp, drawn under every body and wall in the y-sorted list. Nothing touches the sim. STANDARD and CLASSIC draw none.
var LSHAD={n:0,list:[]};
function gfxShadowPass(dt){
  LSHAD.list.length=0;
  if(!gfxHook('shadow')) return false;
  if(((typeof gfxLightNow==='function')?gfxLightNow():CFG.gfxLight)!==2||CFG.gfxLight===0||CFG.gfxLight===1||!G||!G.lights||!G.lights.length||!wc) return false;
  if(LMAP.errG===G&&LMAP.err>=3) return false;
  var lf=wx().lights*(isDay()?tod().lights:1), Z=ZOOM(), VW=W/Z, VH=H/Z, ox=VX, oy=VY, B=[G.player], i, k, j, b, L, dx, dy, d, fk, w, best, e, ux, uy, rx, al, off, lift, sx, sy;
  if(!(lf>0.02)) return false;
  for(i=0;i<VIS.length;i++) B.push(VIS[i]);
  if(NET.on&&NET.up) for(i=0;i<NET.up.length;i++){ try{ if(netUpShown(NET.up[i])) B.push(NET.up[i]); }catch(_nu){} }
  for(k=0;k<B.length;k++){
    b=B[k];
    if(!b||!isFinite(b.x)||!isFinite(b.y)) continue;
    if(b.x<ox-80||b.x>ox+VW+80||b.y<oy-80||b.y>oy+VH+80) continue;
    best=[];
    for(i=0;i<G.lights.length;i++){
      L=G.lights[i]; dx=b.x-L.x; dy=b.y-L.y;
      if(dx>L.r||dx<-L.r||dy>L.r||dy<-L.r) continue;
      d=Math.sqrt(dx*dx+dy*dy);
      if(d>=L.r||d<6) continue;
      fk=(L.fl?(.72+.28*Math.sin(G.t*11+L.f)):1)*lf;
      w=L.i*(1-d/L.r)*fk;
      if(w<.03) continue;
      e={L:L,d:d,dx:dx,dy:dy,w:w};
      if(best.length<2) best.push(e); else if(w>best[0].w||w>best[1].w){ if(best[0].w<best[1].w) best[0]=e; else best[1]=e; }
    }
    for(j=0;j<best.length;j++){
      e=best[j]; ux=e.dx/e.d; uy=e.dy/e.d;
      try{ if(rayHitG(e.L.x,e.L.y,ux,uy,e.d)<e.d-3) continue; }catch(_rh){}
      rx=8+18*(e.d/e.L.r); al=Math.min(.34,.9*e.w); off=rx*.85;
      lift=drawLift((G.map&&G.map.liftAt)?G.map.liftAt(b.x,b.y):0);
      sx=b.x+ux*off; sy=b.y-lift+uy*off;
      wc.save();
      try{ wc.translate(sx,sy); wc.rotate(Math.atan2(uy,ux)); shadowE(0,0,rx,4.5,al); } finally { wc.restore(); }
      LSHAD.list.push({b:b,x:sx,y:sy,a:al}); LSHAD.n++;
    }
  }
  return true;
}

