 run:function(){
   if(!(window.__gfxStage&&window.__frame&&window.__state&&window.__endRaid)||typeof render2D!=='function') return 'SKIP: this fixture cannot stage and draw a raid frame';
   if(typeof LSHAD==='undefined'||typeof gfxShadowPass!=='function') return 'no body shadows from lamps: no LSHAD';
   var bad=[], g=null, p, gl0=CFG.gfxLight, L0=null, E0=null, F0=null, keepSP=gfxShadowPass, stamps=0, r1, r2, r3, own, od;
