   function frame(q){
     CFG.gfxLight=q; stamps=0;
     gfxShadowPass=function(dt){
       own=Object.prototype.hasOwnProperty.call(wc,'drawImage'); od=wc.drawImage;
       var W0=wc; W0.drawImage=function(img){ if(isShad(img)) stamps++; return od.apply(this,arguments); };
       try{ return keepSP(dt); } finally { if(own) W0.drawImage=od; else delete W0.drawImage; }
     };
     try{ __frame(0); } finally { gfxShadowPass=keepSP; }
     var mine=LSHAD.list.filter(function(s){ return s.b===p; });
     return {mine:mine,stamps:stamps};
   }
   try{
     __resetCfg();
     g=__gfxStage({cond:'night',wx:'clear',frames:3});
     if(!g) return 'SKIP: __gfxStage built no raid';
     if(isDay()) return 'SKIP: the staged raid is not at night';
     p=g.player; G.shake=0; G.lightning=0;
     L0=G.lights; E0=G.ents; F0=G.flashes; G.ents=[]; G.flashes=[];
     var dirs=[[-1,0],[1,0],[0,-1],[0,1]], dv=null;
     for(var q=0;q<dirs.length&&!dv;q++){ if(rayHitG(p.x+dirs[q][0]*40,p.y+dirs[q][1]*40,-dirs[q][0],-dirs[q][1],40)>=39) dv=dirs[q]; }
     if(!dv) return 'SKIP: staging: walls on every side of him';
     G.lights=[{x:p.x+dv[0]*40,y:p.y+dv[1]*40,r:180,c:'#ffbe6a',i:.45,f:0,fl:false}];
     for(var k=0;k<3;k++) __frame(0.12);
