     G.lights=[];
     r3=frame(2);
     if(r3.mine.length||r3.stamps) bad.push('with no lamp there are still '+r3.mine.length+' lamp shadows of him');
   }catch(err){ bad.push('threw: '+(err&&err.message||err)); }
   finally{
     gfxShadowPass=keepSP; CFG.gfxLight=gl0;
     try{ if(g&&G===g){ if(L0) G.lights=L0; if(E0) G.ents=E0; G.flashes=F0||[]; } }catch(_r){}
     try{ var g2=__state(); if(g2&&!g2.over) __endRaid('abandon'); }catch(_e){}
     __topClear(); __cleanProfile();
   }
   return bad.length?bad.join('; '):null; }},
